<div class="d-flex justify-content-between mb-3"><div><h2 class="fw-bold"><?=e($order['order_no'])?></h2><div class="text-muted"><?=e($order['customer'])?> · <?=e($order['customer_phone'])?></div></div><a class="btn btn-outline-dark" href="<?=e(base_url('orders'))?>">Retour</a></div><div class="row g-3"><div class="col-lg-7"><div class="km-card p-3"><h5>Articles</h5><table class="table"><thead><tr><th>Produit</th><th>Qté</th><th>Prix</th><th>Sous-total</th></tr></thead><tbody><?php foreach($order['items'] as $i):?><tr><td><?=e($i['name'])?></td><td><?=e($i['quantity'])?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['subtotal'])?></td></tr><?php endforeach;?></tbody></table><div class="d-flex justify-content-end fs-5"><strong>Total: <?=money($order['total'])?></strong></div></div><div class="km-card p-3 mt-3"><h5>Livraison / retrait</h5><p><strong><?=e($order['fulfillment'])?></strong></p><?php if($order['fulfillment']==='LIVRAISON'):?><p><?=e($order['commune'].' / '.$order['quartier'].' / '.$order['avenue'].' '.$order['number'])?><br><?=e($order['reference_text'])?></p><?php endif;?></div></div><div class="col-lg-5"><div class="km-card p-3"><h5>Changer le statut</h5><form method="post" action="<?=e(base_url('orders/'.$order['id'].'/status'))?>"><?=csrf_field()?><select class="form-select" name="status"><?php foreach(['NOUVELLE','CONFIRMEE','EN_PREPARATION','PRETE','EN_LIVRAISON','LIVREE','ANNULEE'] as $s):?><option <?=selected($order['status'],$s)?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-km mt-2" data-confirm="Confirmer le changement de statut ?">Mettre à jour</button></form><hr><h5>Affecter un livreur</h5><form method="post" action="<?=e(base_url('orders/'.$order['id'].'/assign'))?>"><?=csrf_field()?><select class="form-select" name="delivery_user_id"><?php foreach($deliveryUsers as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'])?></option><?php endforeach;?></select><button class="btn btn-dark mt-2">Affecter</button></form></div></div></div>